files.ledger.py:
from operations import apply_transfer

class Ledger:
    def __init__(self, balances):
        self.balances = dict(balances)
        self.seen = set()

    def transfer(self, request_id, source, target, amount):
        if request_id in self.seen:
            return False
        self.seen.add(request_id)
        apply_transfer(self.balances, source, target, amount)
        return True

files.operations.py:
def apply_transfer(balances, source, target, amount):
    balances[source] -= amount
    balances[target] += amount

