for index,(source,target,amount,error) in enumerate([("a","b",0,ValueError),("a","b",-1,ValueError),("a","b",True,ValueError),("a","b",1.5,ValueError),("a","missing",1,KeyError),("missing","b",1,KeyError),("a","a",1,ValueError),("a","b",99,ValueError)]):
    before=dict(x.balances);request="bad-"+str(index)
    try:
        x.transfer(request,source,target,amount)
    except error:
        pass
    else:
        raise AssertionError((source,target,amount))
    assert x.balances==before
    assert request not in x.seen
